function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function getTelegramContext(source) {
  const payload = source.payload || {};
  const message = source.message || payload.message || payload.body?.message || {};
  const chatId = source.chatId || message.chat?.id || payload.chatId || '';
  const rawText = String(source.rawText || source.text || message.text || message.caption || payload.text || '').trim();
  return { payload, message, chatId, rawText };
}

function cleanName(value) {
  return String(value || '')
    .trim()
    .replace(/^[\"'“”‘’]+|[\"'“”‘’]+$/g, '')
    .replace(/\s+/g, ' ');
}

const source = $('Execute Workflow Trigger').item.json || {};
const ctx = getTelegramContext(source);
const raw = ctx.rawText;
const text = normalize(raw);
const prefixes = ['doc sheet', 'xem sheet', 'read sheet'];
let body = raw;
for (const prefix of prefixes) {
  if (text.startsWith(prefix + ' ')) {
    body = raw.slice(prefix.length + 1).trim();
    break;
  }
}

let range = source.range || source.payload?.range || '';
const rangeMatch = body.match(/([A-Za-z]+\d+(?::[A-Za-z]+\d+)?)/);
if (!range && rangeMatch) range = rangeMatch[1].toUpperCase();

let sheetId = source.spreadsheetId || source.sheetId || source.fileId || source.targetId || '';
let sheetName = cleanName(source.sheetName || source.fileName || body.replace(rangeMatch ? rangeMatch[0] : '', '').trim());
if (!range) range = 'A1:Z30';

return [{
  json: {
    ...source,
    payload: ctx.payload,
    message: ctx.message,
    chatId: ctx.chatId,
    rawText: raw,
    text,
    spreadsheetId: sheetId,
    sheetName,
    range,
    hasTarget: Boolean(sheetId || sheetName),
    response: (sheetId || sheetName) ? '' : '📖 <b>Doc Google Sheet</b>\n\nVi du: <code>doc sheet Chi tieu</code>'
  }
}];

const source = $('Prepare Action').item.json || {};
const rows = $input.all().map((item) => item.json || {}).filter((item) => item.id || item.name);
if (!rows.length) {
  return [{ json: { ...source, spreadsheetId: '', response: 'Khong tim thay Google Sheet phu hop.' } }];
}
const sheet = rows[0];
return [{ json: { ...source, spreadsheetId: sheet.id || source.spreadsheetId || '', sheetName: sheet.name || source.sheetName || '', webViewLink: sheet.webViewLink || '' } }];

function escapeHtml(value = '') {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\"/g, '&quot;');
}

const source = $('Prepare Action').item.json || {};
const result = $input.item.json || {};
const rows = Array.isArray(result.values) ? result.values : [];
const limited = rows.slice(0, 30);
let preview = limited.map((row, index) => `${index + 1}. ${row.map((cell) => String(cell)).join(' | ')}`).join('\n');
let truncated = false;
if (rows.length > 30) truncated = true;
if (preview.length > 3000) {
  preview = preview.slice(0, 3000);
  truncated = true;
}
const sheetId = source.spreadsheetId || '';
const link = source.webViewLink || (sheetId ? `https://docs.google.com/spreadsheets/d/${sheetId}/edit` : '');

if (!source.chatId) {
  throw new Error('Missing chatId while formatting Google Sheets read response.');
}

let text = '📖 <b>Noi dung Google Sheet</b>\n\n';
text += `<b>${escapeHtml(source.sheetName || 'Khong ro ten')}</b>\n`;
if (sheetId) text += `ID: <code>${escapeHtml(sheetId)}</code>\n`;
text += `Range: <code>Sheet1!${escapeHtml(source.range || 'A1:Z30')}</code>\n`;
if (link) text += `🔗 <a href="${escapeHtml(link)}">Mo bang tinh</a>\n`;
text += '\n<b>Du lieu xem truoc:</b>\n';
text += `<pre>${escapeHtml(preview || '(Khong co du lieu)')}</pre>`;
if (truncated) text += '\n<i>Noi dung da duoc rut gon.</i>';

return [{ json: { chatId: source.chatId, text: text.trim() } }];
